let loaded=false,auto=true,sound=false,audio=null,sfxBus=null,noise=null,keys=new Set(),heldFire=false,pointer=null,aim={x:0,y:0},noticeUntil=0,toastUntil=0,hurtFlash=0,screenFlash=0,last=performance.now(),accumulator=0,hudAt=0,frameCount=0,fpsAt=performance.now(),fps=60,shaking=0,settingsFrom='menu',lastTarget=null;
function unlockAudio(){if(!audio){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audio=new AC();sfxBus=audio.createGain();sfxBus.gain.value=.16;sfxBus.connect(audio.destination);noise=audio.createBuffer(1,audio.sampleRate*.35,audio.sampleRate);const data=noise.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);}if(audio.state==='suspended')audio.resume().catch(()=>{});}
