 if(type==='reward'){const label=WEAPONS[data]?.name||{shield:'BARRIER +65',repair:'SUIT REPAIR +40',special:'SHOCKWAVE +2',overdrive:'OVERDRIVE · 14s'}[data];toast(label);tone(620,.3,'triangle',.25,1000);}
