$('start').onclick=deploy;$('again').onclick=deploy;$('pause').onclick=()=>pause();$('resume').onclick=()=>pause();$('quit').onclick=command;$('command').onclick=command;$('special').onclick=()=>{unlockAudio();battle.special();};$('auto').onclick=()=>{auto=!auto;$('auto').setAttribute('aria-pressed',String(auto));};
