$('settingsButton').onclick=()=>{settingsFrom=battle.mode==='playing'||battle.mode==='paused'?'pausePanel':$('endPanel').hidden?'menu':'endPanel';pause(true);showPanel('settings');$('technical').textContent=software?'Compatibility renderer active. Detailed skeletal models are projected in software. Hardware graphics are used automatically when WebGL 2 is available.':'Hardware 3D active. Use Battery Saver to reduce resolution and disable dynamic shadows.';};$('closeSettings').onclick=()=>showPanel(settingsFrom);
