function hud(){const p=battle.player,c=battle.config;$('sector').textContent=`SECTOR ${String(battle.level+1).padStart(2,'0')} / 12`;$('levelName').textContent=c.name;$('phase').textContent=battle.phase==='boss'?'GUARDIAN / TARGET THE EXPOSED CORE':battle.phase==='clear'?'SECTOR SECURED':'MARCH / BREAK THE FORMATION';$('score').textContent=String(battle.score).padStart(6,'0');$('ships').textContent=Array(Math.max(0,battle.lives)).fill('◈').join(' ');$('combo').textContent=battle.combo>=3?`${battle.combo} CHAIN · ×${Math.min(5,1+Math.floor(battle.combo/5))}`:'';$('healthText').textContent=String(Math.ceil(p.hp));$('healthFill').style.width=`${p.hp}%`;$('healthFill').style.background=p.hp<30?'#f29c7e':'#c3e1a6';$('shieldFill').style.width=`${p.shield}%`;$('weaponLabel').textContent=WEAPONS[battle.weapon].name;$('weaponText').textContent=battle.overdrive>0?`OVERDRIVE · ${Math.ceil(battle.overdrive)}s`:auto?'AUTO FIRE · ACTIVE':'MANUAL FIRE';$('specialCount').textContent=String(battle.specials);$('special').disabled=battle.specials<=0;$('progressFill').style.width=`${Math.min(100,battle.stageTime/72*100)}%`;const boss=battle.boss;$('bossHud').hidden=!(boss?.alive&&battle.phase==='boss'&&['playing','paused'].includes(battle.mode));if(boss){$('bossName').textContent=boss.name;$('bossFill').style.width=`${Math.max(0,boss.hp/boss.maxHp*100)}%`;$('bossPhase').textContent=`PHASE ${boss.phase} / SHOOT THE GLOWING CORE`;}}
